const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.recipe_id && !body.recipe) {
  errors.push('Missing required parameter: recipe_id or recipe object');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Build search text from recipe
let searchText = '';
if (body.recipe) {
  const r = body.recipe;
  searchText = `${r.title || ''} ${r.description || ''} ${(r.tags || []).join(' ')} ${(r.ingredients || []).map(i => i.name).join(' ')}`;
}

return [{
  json: {
    valid: true,
    recipe_id: body.recipe_id,
    recipe: body.recipe,
    search_text: searchText,
    limit: body.limit || 5,
    exclude_self: body.exclude_self !== false,
    user_id: body.user_id,
    qdrant_url: body.qdrant_url || process.env.QDRANT_URL || 'http://localhost:6333',
    qdrant_api_key: body.qdrant_api_key || process.env.QDRANT_API_KEY,
    openai_api_key: body.openai_api_key || process.env.OPENAI_API_KEY,
    collection: 'recipes'
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

if (input.result?.vector) {
  return [{
    json: {
      ...prevData,
      embedding: input.result.vector,
      source_recipe: input.result.payload
    }
  }];
}

// Fallback: create embedding from payload
const payload = input.result?.payload || {};
const searchText = `${payload.title || ''} ${payload.description || ''} ${(payload.tags || []).join(' ')}`;

return [{
  json: {
    ...prevData,
    search_text: searchText,
    source_recipe: payload,
    need_embedding: true
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

return [{
  json: {
    ...prevData,
    embedding: input.data[0].embedding,
    source_recipe: prevData.recipe
  }
}];

const input = $input.first().json;
const prevData = $('Merge').first().json;

try {
  let results = (input.result || []).map(item => ({
    id: item.id,
    score: item.score,
    recipe: item.payload || {}
  }));

  // Exclude self if requested
  if (prevData.exclude_self && prevData.recipe_id) {
    results = results.filter(r => r.id !== prevData.recipe_id);
  }

  // Limit results
  results = results.slice(0, prevData.limit);

  return [{
    json: {
      success: true,
      data: {
        source_recipe: prevData.source_recipe,
        similar_recipes: results,
        total: results.length
      },
      meta: {
        provider: 'qdrant',
        collection: prevData.collection
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to process similar recipes: ' + e.message,
        status: 'PROCESS_ERROR'
      },
      meta: { provider: 'qdrant' }
    }
  }];
}
